from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
import numpy as np

def simon_oracle(period):
    n = len(period)
    qc = QuantumCircuit(2 * n, name="Simon_Oracle")

    for i in range(n):
        if period[i] == '1':
            qc.cx(i, n + i)

    for i in range(n):
        if period[i] == '1':
            for j in range(n):
                qc.cx(i, n + j)
            break

    return qc

def gaussian_elimination_gf2(equations, n):
    matrix = [list(row) for row in equations]
    pivot_row = 0
    pivot_cols = []

    for col in range(n):
        found = False
        for row in range(pivot_row, len(matrix)):
            if matrix[row][col] == 1:
                matrix[pivot_row], matrix[row] = matrix[row], matrix[pivot_row]
                found = True
                break

        if found:
            pivot_cols.append(col)
            for row in range(len(matrix)):
                if row != pivot_row and matrix[row][col] == 1:
                    matrix[row] = [(matrix[row][k] + matrix[pivot_row][k]) % 2 for k in range(n)]
            pivot_row += 1

    s = [0] * n
    for i, col in enumerate(pivot_cols):
        s[col] = matrix[i][col]
        for k in range(n):
            if k != col and matrix[i][k] == 1:
                s[col] = 0
                break

    return s

def main():
    n = 5
    period = "10100"

    qc = QuantumCircuit(2 * n, n)

    for i in range(n):
        qc.h(i)

    oracle = simon_oracle(period)
    qc.compose(oracle, inplace=True)

    for i in range(n):
        qc.h(i)

    qc.measure(range(n), range(n))

    simulator = AerSimulator()
    transpiled_qc = transpile(qc, simulator)
    result = simulator.run(transpiled_qc, shots=1024).result()
    counts = result.get_counts()

    print(f"Simulated period (s): {period}")
    print(f"Measurement results: {counts}")

    equations = []
    for bitstring in counts.keys():
        y = [int(bit) for bit in bitstring[::-1]]
        if any(v == 1 for v in y):
            equations.append(y)

    s = gaussian_elimination_gf2(equations, n)
    s_str = "".join(str(bit) for bit in s[::-1])

    print(f"Recovered period (s): {s_str}")

if __name__ == "__main__":
    main()

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator

def simons_oracle(qc, n, s):
    for i in range(n):
        if s[i] == '1':
            qc.cx(i, n + i)
    for i in range(n):
        qc.cx(i, n + i)

def run_simons_algorithm(s_str, shots=2000):
    n = len(s_str)
    qc = QuantumCircuit(2 * n, n)
    for i in range(n):
        qc.h(i)
    simons_oracle(qc, n, s_str)
    for i in range(n):
        qc.h(i)
    for i in range(n):
        qc.measure(i, i)

    simulator = AerSimulator()
    transpiled_qc = transpile(qc, simulator)
    job = simulator.run(transpiled_qc, shots=shots)
    result = job.result()
    counts = result.get_counts()

    equations = []
    for outcome, count in counts.items():
        y = [int(bit) for bit in reversed(outcome)]
        if any(bit == 1 for bit in y):
            equations.append(y)

    unique_equations = []
    seen = set()
    for eq in equations:
        t = tuple(eq)
        if t not in seen:
            seen.add(t)
            unique_equations.append(eq)

    A = np.array(unique_equations, dtype=int) if unique_equations else np.empty((0, n), dtype=int)

    def gf2_gauss_jordan(matrix):
        M = [row[:] for row in matrix.tolist()]
        rows = len(M)
        cols = len(M[0]) if rows > 0 else 0
        pivot_row = 0
        pivot_cols = []
        for col in range(cols):
            found = -1
            for r in range(pivot_row, rows):
                if M[r][col] == 1:
                    found = r
                    break
            if found == -1:
                continue
            M[pivot_row], M[found] = M[found], M[pivot_row]
            for r in range(rows):
                if r != pivot_row and M[r][col] == 1:
                    M[r] = [(a + b) % 2 for a, b in zip(M[r], M[pivot_row])]
            pivot_cols.append(col)
            pivot_row += 1
            if pivot_row == rows:
                break
        return M, pivot_cols

    M, pivot_cols = gf2_gauss_jordan(A)
    rank = len(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_cols]

    candidates = []
    if rank == n - 1:
        for free_val in [0, 1]:
            x = [0] * n
            for idx, fc in enumerate(free_cols):
                x[fc] = free_val
            for r in range(rank):
                pc = pivot_cols[r]
                x[pc] = M[r][free_cols[0]] * free_val % 2
            candidates.append(x)
    elif rank == n:
        candidates.append([0] * n)

    recovered = None
    for cand in candidates:
        if all(c == 0 for c in cand):
            continue
        recovered = cand
        break
    if recovered is None:
        recovered = [0] * n

    recovered_str = ''.join(str(bit) for bit in reversed(recovered))
    return counts, recovered_str

if __name__ == "__main__":
    hidden_s = '0100'
    counts, recovered_s = run_simons_algorithm(hidden_s)
    print("Hidden period s:", hidden_s)
    print("Measurement counts:", counts)
    print("Recovered period s:", recovered_s)
    print("Match:", hidden_s == recovered_s)

import numpy as np
from scipy.stats import chisquare
import qsharp

# Modern Q# (qdk) API: init with a target profile, then use qsharp.eval / qsharp.run.
# The new QDK capabilities checker rejects `if <Result> == One` (dynamic classical
# feedback) for QIR targets, so the feed-forward corrections are applied *coherently*
# using the unmeasured msg/here qubits as controls before the final measurement.
# This is the standard unitary-teleportation circuit and reproduces the corrected
# receiver statistics exactly.
qsharp.init(target_profile=qsharp.TargetProfile.Unrestricted)

QSHARP_CODE = r"""
open Microsoft.Quantum.Measurement;

operation PrepareRyState(q : Qubit) : Unit {
    Ry(2.538, q);
}

operation TeleportRyState() : Result {
    use (msg, here, there) = (Qubit(), Qubit(), Qubit());
    // Prepare Ry(2.538)|0> on msg
    PrepareRyState(msg);
    // Create Bell pair (here, there)
    H(here);
    CNOT(here, there);
    // Bell measurement (coherent): CNOT msg->here, H msg
    CNOT(msg, here);
    H(msg);
    // Coherent X/Z corrections on the receiver using msg and here as controls.
    // After H(msg), msg is in the measurement basis; a Z correction on `there`
    // controlled on msg == |1> implements the phase flip, and an X correction
    // controlled on here == |1> implements the bit flip.
    Controlled Z([msg], there);
    Controlled X([here], there);
    // Measure the receiver
    let result = MResetZ(there);
    Reset(msg);
    Reset(here);
    return result;
}
"""
qsharp.eval(QSHARP_CODE)

shots = 1000
results = qsharp.run("TeleportRyState()", shots)

ones = sum(1 for r in results if str(r) == "One")
zeros = shots - ones

theta = 2.538
p0_theory = np.cos(theta / 2) ** 2
p1_theory = np.sin(theta / 2) ** 2

exp0 = shots * p0_theory
exp1 = shots * p1_theory
chi2_stat, p_value = chisquare([zeros, ones], [exp0, exp1])

print("=" * 60)
print("Quantum teleportation (Ry(2.538)|0>) — modern Q# / qdk")
print("Coherent (unitary) feed-forward corrections")
print("=" * 60)
print(f"Shots: {shots}")
print(f"Receiver |0> count: {zeros}")
print(f"Receiver |1> count: {ones}")
print(f"Observed P(|0>): {zeros/shots:.4f}")
print(f"Observed P(|1>): {ones/shots:.4f}")
print()
print(f"Theoretical P(|0>): {p0_theory:.4f}")
print(f"Theoretical P(|1>): {p1_theory:.4f}")
print()
print(f"Expected |0> count: {exp0:.2f}")
print(f"Expected |1> count: {exp1:.2f}")
print()
print(f"Chi-square statistic: {chi2_stat:.4f}")
print(f"P-value: {p_value:.4f}")
if p_value > 0.01:
    print("Result: PASS - Observed distribution matches theory (p > 0.01)")
else:
    print("Result: FAIL - Observed distribution deviates from theory (p <= 0.01)")

from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator

qasm_program = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[6] q;
bit[6] c;

h q[0];
cx q[0], q[1];
cx q[1], q[2];
cx q[2], q[3];
cx q[3], q[4];
cx q[4], q[5];

c = measure q;
"""

def main():
    qc = qiskit.qasm3.loads(qasm_program)
    backend = AerSimulator()
    tqc = transpile(qc, backend)
    job = backend.run(tqc, shots=2000)
    result = job.result()
    counts = result.get_counts()
    print("6-qubit GHZ state measurement counts (2000 shots):")
    for outcome, count in sorted(counts.items()):
        print(f"  {outcome}: {count}")

if __name__ == "__main__":
    import qiskit.qasm3
    main()

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
from qiskit.exceptions import QiskitError

def gf2_gauss_jordan(M):
    A = M.copy() % 2
    rows, cols = A.shape
    pivot_cols = []
    r = 0
    for c in range(cols):
        pivot = np.argmax(A[r:, c]) + r
        if A[pivot, c] == 0:
            continue
        A[[r, pivot]] = A[[pivot, r]]
        for r2 in range(rows):
            if r2 != r and A[r2, c] == 1:
                A[r2] = (A[r2] + A[r]) % 2
        pivot_cols.append(c)
        r += 1
        if r == rows:
            break
    return A, pivot_cols

def solve_gf2(M):
    rows, cols = M.shape
    A, pivot_cols = gf2_gauss_jordan(M)
    rank = len(pivot_cols)
    if rank == cols:
        return np.zeros(cols, dtype=int)
    free_cols = [c for c in range(cols) if c not in pivot_cols]
    sol = np.zeros(cols, dtype=int)
    sol[free_cols[0]] = 1
    for i, pc in enumerate(pivot_cols):
        sol[pc] = A[i, free_cols[0]]
    return sol

def simons_oracle(n, s):
    qc = QuantumCircuit(2 * n, name="U_f")
    for i in range(n):
        qc.cx(i, n + i)
    if '1' in s:
        s_bits = [int(b) for b in s]
        for i in range(n):
            if s_bits[i] == 1:
                qc.cx(0, n + i)
    return qc

def run_simons_algorithm(s='1111', shots=200):
    n = len(s)
    qc = QuantumCircuit(2 * n, n)
    for i in range(n):
        qc.h(i)
    oracle = simons_oracle(n, s)
    qc.append(oracle, range(2 * n))
    for i in range(n):
        qc.h(i)
    qc.measure(range(n), range(n))

    simulator = AerSimulator()
    try:
        transpiled = transpile(qc, simulator, optimization_level=0)
    except QiskitError:
        transpiled = transpile(qc, simulator, optimization_level=1)
    result = simulator.run(transpiled, shots=shots).result()
    counts = result.get_counts()

    equations = []
    for y_str in counts:
        y = np.array([int(b) for b in y_str], dtype=int)
        if np.any(y):
            equations.append(y)

    if not equations:
        return s, '0' * n, counts

    M = np.array(equations, dtype=int) % 2
    s_recovered_vec = solve_gf2(M)
    s_recovered = ''.join(str(b) for b in s_recovered_vec)
    return s, s_recovered, counts

if __name__ == "__main__":
    true_s, recovered_s, counts = run_simons_algorithm('1111', shots=200)
    print("True hidden string s:        ", true_s)
    print("Recovered hidden string s:   ", recovered_s)
    print("Match:                       ", true_s == recovered_s)
    print("Measurement sample counts:   ", dict(list(counts.items())[:10]))
